  const supplied=route.url&&/^https?:\/\//.test(route.url)?route.url:null;let base=baseUrl,requestPath=path;if(supplied){try{const url=new URL(supplied);base=url.origin;requestPath=template(url.pathname+url.search);}catch{}}else if(route.host&&/^https?:\/\//.test(route.host))base=route.host;
  activeRoute={...route,path:requestPath};el('apiBaseUrl').value=base;el('url').value=base?base.replace(/\/$/,'')+requestPath:requestPath;el('route').textContent=[route.service,route.handler,route.where].filter(Boolean).join(' · ')||'Source route; add a base URL to execute it.';el('apiAuthProfile').value='';authChoice=null;dirty=false;typedParameters();authProfiles();notice(base?'Request prepared. Review parameters and authentication before sending.':'Add the service base URL to prepare this source route.');
