 async function inventory(){const n=++routeVersion;try{const r=await tool('api_routes',{q:el('apiRouteSearch').value}),items=r.routes||r.rows||r.items||(Array.isArray(r)?r:[]);if(n!==routeVersion)return;const root=el('apiRoutes');root.replaceChildren();for(const route of items.slice(0,200)){const b=document.createElement('button');b.className='item';b.innerHTML='<span class="pill '+E(route.method)+'">'+E(route.method||'ANY')+'</span> '+E(route.path||route.url)+'<small>'+E(route.service||route.site||route.host||'Source route')+'</small>';b.onclick=()=>choose(route);root.append(b);}if(!root.children.length)root.innerHTML='<p class="muted">No matching routes. Build a passport or capture UI traffic to discover endpoints.</p>';}catch(e){el('apiRoutes').textContent=e.message;}}
