 const tabs=[...document.querySelectorAll('[role=tab]')];for(const b of tabs){const group=b.closest('[role=tablist]');b.tabIndex=b.getAttribute('aria-selected')==='true'?0:-1;b.addEventListener('click',()=>{for(const other of group.querySelectorAll('[role=tab]'))other.tabIndex=other===b?0:-1;});}for(const list of document.querySelectorAll('[role=tablist]'))list.addEventListener('keydown',e=>{const buttons=[...list.querySelectorAll('[role=tab]')],i=buttons.indexOf(e.target),j=e.key==='ArrowRight'?(i+1)%buttons.length:e.key==='ArrowLeft'?(i+buttons.length-1)%buttons.length:e.key==='Home'?0:e.key==='End'?buttons.length-1:null;if(i>=0&&j!==null){e.preventDefault();buttons[j].click();buttons[j].focus();}});
